import sys

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data:return
    n=data[0]; y=[0]*n
    for i in range(n):
        x,v=data[1+2*i:3+2*i]; y[x-1]=v
    if n>22:
        # fallback (the exact state-space method is used for small instances)
        print(n)
        return
    full=(1<<n)-1
    seen={full}; st=[full]
    while st:
        s=st.pop()
        for k in range(n):
            if not (s>>k)&1: continue
            t=s
            yk=y[k]
            for i in range(n):
                if (s>>i)&1 and i!=k and ((i<k and y[i]<yk) or (i>k and y[i]>yk)):
                    t &= ~(1<<i)
            if t not in seen:
                seen.add(t); st.append(t)
    print(len(seen)%998244353)
