import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]

    factors = {}
    for i, x in enumerate(a):
        d = 2
        while d * d <= x:
            if x % d == 0:
                e = 0
                while x % d == 0:
                    x //= d
                    e += 1
                factors.setdefault(d, []).append((i, e))
            d += 1
        if x > 1:
            factors.setdefault(x, []).append((i, 1))

    answer = 1
    for p, edges in factors.items():
        dp = {0: 1}
        previous = -1
        vertices = 1

        for index, step in edges:
            gap = index - previous - 1
            if gap:
                dp = {h: value * pow(p, h * gap, MOD) % MOD
                      for h, value in dp.items()}
                vertices += gap

            nxt = {}
            for h, value in dp.items():
                nh = h + step
                nxt[nh] = (nxt.get(nh, 0) + value * pow(p, nh, MOD)) % MOD

                if h >= step:
                    nh = h - step
                    contribution = value * pow(p, nh, MOD) % MOD
                else:
                    nh = 0
                    contribution = value * pow(p, vertices * (step - h), MOD) % MOD
                nxt[nh] = (nxt.get(nh, 0) + contribution) % MOD

            dp = nxt
            vertices += 1
            previous = index

        gap = n - 2 - previous
        if gap:
            dp = {h: value * pow(p, h * gap, MOD) % MOD
                  for h, value in dp.items()}

        answer = answer * (sum(dp.values()) % MOD) % MOD

    print(answer)

if __name__ == '__main__':
    main()

