import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    values = data[1:1+n]
    limit = max(values)
    spf = list(range(limit + 1))
    if limit >= 1:
        spf[1] = 1
    i = 2
    while i * i <= limit:
        if spf[i] == i:
            for j in range(i * i, limit + 1, i):
                if spf[j] == j:
                    spf[j] = i
        i += 1
    nim = 0
    for x in values:
        count = 0
        while x > 1:
            x //= spf[x]
            count += 1
        nim ^= count
    sys.stdout.write('Anna\n' if nim else 'Bruno\n')

