import sys

def solve():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data:return
    n=data[0]; A=data[1:]
    L=61
    bits=[((-a)%(1<<L)) for a in A]
    ans=0
    def dfs(arr,d,score):
        nonlocal ans
        if d==L:
            # exactly one shift remains unresolved; choose its valuation parity favorably
            ans=max(ans,score+1)
            return
        z=[]; o=[]
        for j in arr:
            if (bits[j]>>d)&1:z.append(j)
            else:o.append(j)
        good=(d%2==0)
        # choose bit 0: ones diverge
        if o:
            dfs(o,d+1,score+(len(z) if good else 0))
        else:
            ans=max(ans,score+(len(z) if good else 0))
        # choose bit 1: zeros diverge
        if z:
            dfs(z,d+1,score+(len(o) if good else 0))
        else:
            ans=max(ans,score+(len(o) if good else 0))
    dfs(list(range(n)),0,0)
    print(ans)
