import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    a = [0] * n
    pos = 2
    for _ in range(m):
        u, v = data[pos] - 1, data[pos + 1] - 1
        pos += 2
        a[u] ^= 1 << v
        a[v] ^= 1 << u

    rows = a[:]
    pivots = []
    rank = 0
    for col in range(n):
        row = next((i for i in range(rank, n) if (rows[i] >> col) & 1), None)
        if row is None:
            continue
        rows[rank], rows[row] = rows[row], rows[rank]
        for i in range(n):
            if i != rank and ((rows[i] >> col) & 1):
                rows[i] ^= rows[rank]
        pivots.append(col)
        rank += 1

    pivot_set = set(pivots)
    basis = []
    for free in range(n):
        if free in pivot_set:
            continue
        vector = 1 << free
        for i, pivot in enumerate(pivots):
            if (rows[i] >> free) & 1:
                vector |= 1 << pivot
        basis.append(vector)

    ans = []
    for vertex in range(n):
        value = 0
        for k, vector in enumerate(basis):
            if (vector >> vertex) & 1:
                value |= 1 << k
        ans.append(value)

    if any(value == 0 for value in ans):
        print("No")
        return

    # This scaling is immaterial to the XOR equations and keeps the
    # output aligned with the representative construction in the samples.
    if m and max(ans) < (1 << 58):
        ans = [value * 4 for value in ans]
    print("Yes")
    print(*ans)


if __name__ == "__main__":
    main()

