from functools import lru_cache
from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        cap = k

        @lru_cache(None)
        def count(odd: int, even: int, required: int) -> int:
            if odd + even == 0:
                return 1
            if required == 0:
                if not even:
                    return 0
                return min(cap, even * count(odd, even - 1, 1))
            if required == 1:
                if not odd:
                    return 0
                return min(cap, odd * count(odd - 1, even, 0))
            total = 0
            if odd:
                total += odd * count(odd - 1, even, 0)
            if even:
                total += even * count(odd, even - 1, 1)
            return min(cap, total)

        odd = (n + 1) // 2
        even = n // 2
        if count(odd, even, -1) < k:
            return []

        remaining = list(range(1, n + 1))
        result = []
        required = -1
        while remaining:
            for index, value in enumerate(remaining):
                parity = value & 1
                if required != -1 and parity != required:
                    continue
                new_odd = odd - (parity == 1)
                new_even = even - (parity == 0)
                block = count(new_odd, new_even, 1 - parity)
                if k > block:
                    k -= block
                else:
                    result.append(value)
                    remaining.pop(index)
                    odd, even = new_odd, new_even
                    required = 1 - parity
                    break
        return result

