class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        half = (n + 1) // 2

        # Each digit in the first half contributes this coefficient modulo k.
        weights = []
        for i in range(half):
            if n & 1 and i == n // 2:
                weights.append(pow(10, i, k))
            else:
                weights.append((pow(10, i, k) + pow(10, n - 1 - i, k)) % k)

        # suffix[i][r] says that positions i onward can contribute remainder r.
        suffix = [[False] * k for _ in range(half + 1)]
        suffix[half][0] = True
        for i in range(half - 1, -1, -1):
            w = weights[i]
            for digit in range(10):
                for r in range(k):
                    if suffix[i + 1][r]:
                        suffix[i][(digit * w + r) % k] = True

        # Choose digits greedily from left to right, using the suffix table
        # to retain divisibility feasibility.
        left = []
        remainder = 0
        for i, w in enumerate(weights):
            lowest = 1 if i == 0 else 0
            for digit in range(9, lowest - 1, -1):
                needed = (-remainder - digit * w) % k
                if suffix[i + 1][needed]:
                    left.append(str(digit))
                    remainder = (remainder + digit * w) % k
                    break

        first_half = ''.join(left)
        if n & 1:
            return first_half + first_half[-2::-1]
        return first_half + first_half[::-1]

