class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        parent = [-1] * n
        order = [0]
        for u in order:
            for v, w in graph[u]:
                if v != parent[u]:
                    parent[v] = u
                    order.append(v)

        # dp_free[u]: optimum below u when its parent edge is absent
        # dp_used[u]: optimum below u when its parent edge is present
        dp_free = [0] * n
        dp_used = [0] * n

        for u in reversed(order):
            base = 0
            gains = []
            for v, w in graph[u]:
                if parent[v] == u:
                    base += dp_free[v]
                    gains.append(w + dp_used[v] - dp_free[v])

            gains.sort(reverse=True)
            dp_free[u] = base + sum(x for x in gains[:k] if x > 0)
            dp_used[u] = base + sum(x for x in gains[:k - 1] if x > 0)

        return dp_free[0]

