def main():
    it = iter(sys.stdin.buffer.read().split())
    t = int(next(it))
    ans = []
    for _ in range(t):
        h = int(next(it)); w = int(next(it))
        s = [next(it) for _ in range(h)]

        ok = True
        for row in s:
            if row.count(b'A') & 1:
                ok = False
        for j in range(w):
            z = 0
            for i in range(h):
                z ^= (s[i][j] == 65)
            if z:
                ok = False
        if not ok:
            ans.append('0')
            continue

        n = h + w
        parent = list(range(n))
        xr = [0] * n

        def find(x):
            if parent[x] != x:
                y = parent[x]
                parent[x] = find(y)
                xr[x] ^= xr[y]
            return parent[x]

        def unite(a, b, val):
            ra = find(a)
            xa = xr[a]
            rb = find(b)
            xb = xr[b]
            if ra == rb:
                return (xa ^ xb) == val
            parent[ra] = rb
            xr[ra] = xa ^ xb ^ val
            return True

        col_prefix = [0] * w
        for i in range(h):
            row_prefix = 0
            for j, ch in enumerate(s[i]):
                if ch == 66:  # B
                    if not unite(i, h + j, 1 ^ row_prefix ^ col_prefix[j]):
                        ok = False
                else:       # A
                    row_prefix ^= 1
                    col_prefix[j] ^= 1

        if not ok:
            ans.append('0')
        else:
            components = sum(find(x) == x for x in range(n))
            ans.append(str(pow(2, components, MOD)))

    sys.stdout.write('\n'.join(ans))

