class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)

        def occurrences(t):
            m = len(t)
            if m == 0:
                return [True] * (n + 1)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j
            result = [False] * (n + 1)
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    result[i - m + 1] = True
                    j = pi[j - 1]
            return result

        oa = occurrences(a)
        ob = occurrences(b)
        oc = occurrences(c)

        def next_occurrence(ok):
            result = [-1] * (n + 2)
            last = -1
            for i in range(n, -1, -1):
                if ok[i]:
                    last = i
                result[i] = last
            return result

        nb = next_occurrence(ob)
        nc = next_occurrence(oc)
        la, lb, lc = len(a), len(b), len(c)
        answer = n + 1

        for start in range(n + 1):
            if not oa[start] or start + la > n:
                continue
            middle = nb[start + la]
            if middle == -1 or middle + lb > n:
                continue
            end = nc[middle + lb]
            if end != -1:
                answer = min(answer, end + lc - start)

        return -1 if answer == n + 1 else answer

