def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    graph = [[] for _ in range(n)]
    pos = 2
    for _ in range(m):
        x = data[pos] - 1
        y = data[pos + 1] - 1
        z = data[pos + 2]
        pos += 3
        graph[x].append((y, z))
        graph[y].append((x, z))

    value = [0] * n
    seen = [False] * n
    answer = [0] * n

    for start in range(n):
        if seen[start]:
            continue
        seen[start] = True
        stack = [start]
        component = []
        while stack:
            v = stack.pop()
            component.append(v)
            for w, z in graph[v]:
                expected = value[v] ^ z
                if seen[w]:
                    if value[w] != expected:
                        print(-1)
                        return
                else:
                    seen[w] = True
                    value[w] = expected
                    stack.append(w)

        shift = 0
        size = len(component)
        for bit in range(30):
            ones = 0
            mask = 1 << bit
            for v in component:
                if value[v] & mask:
                    ones += 1
            if ones * 2 > size:
                shift |= mask
        for v in component:
            answer[v] = value[v] ^ shift

    print(*answer)

