class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        # For each prefix-index residue, retain the smallest prefix sum seen.
        # Subtracting it from the current prefix gives the best valid subarray.
        minimum = [None] * k
        minimum[0] = 0
        prefix = 0
        answer = None

        for index, value in enumerate(nums, 1):
            prefix += value
            residue = index % k
            if minimum[residue] is not None:
                candidate = prefix - minimum[residue]
                if answer is None or candidate > answer:
                    answer = candidate
            if minimum[residue] is None or prefix < minimum[residue]:
                minimum[residue] = prefix

        return answer

