from typing import List

class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        if n <= 1:
            return 0

        # A line for index i represents dp[i] + (x-i)*nums[i].
        lines = [None] * (4 * n)

        def value(line, x):
            return line[0] * x + line[1]

        def add(node, left, right, line):
            current = lines[node]
            if current is None:
                lines[node] = line
                return
            mid = (left + right) // 2
            if value(line, mid) > value(current, mid):
                lines[node], line = line, current
            if left == right:
                return
            if value(line, left) > value(lines[node], left):
                add(node * 2, left, mid, line)
            elif value(line, right) > value(lines[node], right):
                add(node * 2 + 1, mid + 1, right, line)

        def query(node, left, right, x):
            line = lines[node]
            result = value(line, x) if line is not None else -10**30
            if left == right:
                return result
            mid = (left + right) // 2
            if x <= mid:
                return max(result, query(node * 2, left, mid, x))
            return max(result, query(node * 2 + 1, mid + 1, right, x))

        add(1, 0, n - 1, (nums[0], 0))
        score = 0
        for j in range(1, n):
            score = query(1, 0, n - 1, j)
            add(1, 0, n - 1, (nums[j], score - j * nums[j]))
        return score

