import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        digits = len(str(n))
        low = 10 ** (digits - 1)
        high = 10 ** digits

        is_prime = [True] * high
        is_prime[0] = is_prime[1] = False
        for p in range(2, int(high ** 0.5) + 1):
            if is_prime[p]:
                is_prime[p * p:high:p] = [False] * (((high - 1 - p * p) // p) + 1)

        if is_prime[n] or is_prime[m]:
            return -1

        distances = {n: n}
        queue = [(n, n)]
        place_values = [10 ** (digits - 1 - i) for i in range(digits)]

        while queue:
            cost, value = heapq.heappop(queue)
            if cost != distances.get(value):
                continue
            if value == m:
                return cost

            for place in place_values:
                digit = (value // place) % 10
                if digit > 0:
                    nxt = value - place
                    if nxt >= low and not is_prime[nxt]:
                        new_cost = cost + nxt
                        if new_cost < distances.get(nxt, float('inf')):
                            distances[nxt] = new_cost
                            heapq.heappush(queue, (new_cost, nxt))
                if digit < 9:
                    nxt = value + place
                    if nxt < high and not is_prime[nxt]:
                        new_cost = cost + nxt
                        if new_cost < distances.get(nxt, float('inf')):
                            distances[nxt] = new_cost
                            heapq.heappush(queue, (new_cost, nxt))

        return -1

