class Solution:
    def minOperations(self, n: int, m: int) -> int:
        if n == m:
            return -1 if self._prime(n) else n
        if self._prime(n) or self._prime(m):
            return -1
        d = len(str(n))
        lo = 10 ** (d - 1)
        hi = 10 ** d
        prime = [True] * hi
        if hi > 0: prime[0] = False
        if hi > 1: prime[1] = False
        for i in range(2, int(hi ** 0.5) + 1):
            if prime[i]:
                prime[i*i:hi:i] = [False] * (((hi-1-i*i)//i)+1)
        dist = {n: n}
        pq = [(n,n)]
        while pq:
            cost,x = heapq.heappop(pq)
            if cost != dist.get(x): continue
            if x == m: return cost
            s = list(str(x))
            for j in range(d):
                p = 10 ** (d-1-j)
                digit = int(s[j])
                for delta in (-1,1):
                    nd = digit + delta
                    if 0 <= nd <= 9:
                        y = x + delta*p
                        if y >= lo and y < hi and not prime[y]:
                            nc = cost+y
                            if nc < dist.get(y, 10**30):
                                dist[y]=nc; heapq.heappush(pq,(nc,y))
        return -1
    def _prime(self,x):
        if x<2:return False
        i=2
        while i*i<=x:
            if x%i==0:return False
            i+=1
        return True

