from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i <= right:
                z[i] = min(right - i + 1, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > right:
                left, right = i, i + z[i] - 1

        ans = 0
        for i in range(1, (n - 1) // 2 + 1):
            if z[i] >= i:
                ans += n - 2 * i

        # nxt[b] is the LCP of suffixes beginning at i+1 and i+1+b.
        nxt = [0] * n
        for i in range(n - 2, 0, -1):
            m = n - i
            cur = [0] * (m + 1)
            value = nums[i]
            for b in range(1, m):
                if value == nums[i + b]:
                    cur[b] = nxt[b] + 1
            first_ok = z[i] >= i
            for b in range(1, m // 2 + 1):
                if cur[b] >= b:
                    ans += 1
                    if first_ok and b >= i:
                        ans -= 1
            nxt = cur
        return ans

