        n = len(s)
        while i < n:
            j = i
            while j < n and s[j] == s[i]:
                j += 1
            if s[i] == '0':
                z.append(j-i)
            i = j
        # Internal one runs are those between consecutive zero runs.
        # Extract their lengths in order.
        i = 0
        while i < n:
            j = i
            while j < n and s[j] == s[i]:
                j += 1
            if s[i] == '1':
                # has zero on both sides in original, equivalently not edge
                if i > 0 and j < n:
                    b.append(j-i)
            i = j
        m = len(z)
        if m < 2 or not b:
            return ones
        pre = [0]*(m+1)
        for k in range(m): pre[k+1] = max(pre[k], z[k])
        suf = [0]*(m+1)
        for k in range(m-1,-1,-1): suf[k] = max(suf[k+1], z[k])
        ans = ones
        for k, x in enumerate(b, 1):
            merged = z[k-1] + x + z[k]
            other = max(pre[k-1], suf[k+1])
            ans = max(ans, ones-x+max(merged, other))
        return ans

