class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        ones = s.count('1')
        zero_runs = []
        internal_one_runs = []

        i = 0
        n = len(s)
        while i < n:
            j = i
            while j < n and s[j] == s[i]:
                j += 1
            if s[i] == '0':
                zero_runs.append(j - i)
            elif i > 0 and j < n:
                internal_one_runs.append(j - i)
            i = j

        m = len(zero_runs)
        if m < 2:
            return ones

        prefix = [0] * (m + 1)
        for i in range(m):
            prefix[i + 1] = max(prefix[i], zero_runs[i])
        suffix = [0] * (m + 1)
        for i in range(m - 1, -1, -1):
            suffix[i] = max(suffix[i + 1], zero_runs[i])

        answer = ones
        for i, one_len in enumerate(internal_one_runs, 1):
            merged = zero_runs[i - 1] + one_len + zero_runs[i]
            other = max(prefix[i - 1], suffix[i + 1])
            answer = max(answer, ones - one_len + max(merged, other))
        return answer

